-- Migration: Módulo de Leads
-- Adiciona coluna segment + importa leads exportados do CRM externo (Datacrazy)

-- 1. Adiciona coluna segment em customers
ALTER TABLE customers ADD COLUMN IF NOT EXISTS segment text DEFAULT 'Lead';

-- 2. Índice para busca por segment por tenant
CREATE INDEX IF NOT EXISTS idx_customers_segment ON customers(tenant_id, segment);

-- 3. Importa leads do CSV exportado do CRM Datacrazy
DO $$
DECLARE
  v_tid uuid;
BEGIN
  SELECT id INTO v_tid FROM tenants WHERE slug = 'consult-delivery' LIMIT 1;
  IF v_tid IS NULL THEN
    RAISE NOTICE 'Tenant consult-delivery não encontrado — import ignorado';
    RETURN;
  END IF;

  ON CONFLICT DO NOTHING;

  RAISE NOTICE 'Leads importados com sucesso para tenant %', v_tid;
END$$;
